  function graph(topology,description,labels){
    labels=labels||[];
    var nodes=[],branches=[];
    function add(from,to,kind,label){if(!nodes.includes(from))nodes.push(from);if(!nodes.includes(to))nodes.push(to);branches.push({from:from,to:to,kind:kind,label:label||kind});}
    if(topology==="units")add("given","requested","conversion",labels[0]||"quantity");
    else if(topology==="node")labels.forEach(function(label,i){add("terminal-"+i,"n","referenced-current",label);});
    else if(topology.includes("capacitor")||topology.includes("rc-")){
      if(topology==="capacitor-switch"){add("source","out","switch",labels[0]||"switch");add("out","0","capacitor",labels[1]||"C");}
      else if(topology.includes("rc-")){add("source","out","resistor",labels[0]||"R");add("out","0","capacitor",labels[1]||"C");}
      else add("source","0","capacitor",labels[0]||"C");
    }else if(topology.includes("inductor")||topology.includes("rl-")){
      if(topology.includes("rl-")){add("source","out","resistor",labels[0]||"R");add("out","0","inductor",labels[1]||"L");}
      else add("source","0","inductor",labels[0]||"L");
    }else if(topology.includes("parallel")){
      add("a","b","branch",labels[0]||"branch 1");
      add("a","b","branch",labels[1]||"branch 2");
      if(labels[2])add("a","b","branch",labels[2]);
    }else if(topology.includes("divider")||topology.includes("thevenin")){
      add("source","out","series element",labels[0]||"R1");
      add("out","0","shunt element",labels[1]||"R2");
      if(labels[2]&&!topology.includes("thevenin"))add("out","0","load",labels[2]);
    }else if(topology.includes("opamp")){
      add("vin","input+","signal",labels[0]||"input");
      add("input-","out",topology.includes("comparator")?"open-loop reference":"negative feedback",labels[1]||"feedback");
      add("out","0","output reference",labels[2]||"Vout");
    }else if(topology.includes("digital")){
      add("supply","out","pull or driver",labels[0]||"driver");
      add("out","0","receiver or switch",labels[1]||"receiver");
    }else{
      add("source","n1","source","source");
      labels.forEach(function(label,i){add("n"+(i+1),i===labels.length-1?"0":"n"+(i+2),"component",label);});
      if(!labels.length)add("n1","0","component",topology);
    }
    return{topology:topology,nodes:nodes,branches:branches,description:description,labels:labels};
  }
