  G.sine_peak_rms=function(level,rng){var peak=rng.pick([1,2,5,10,12,20]),inverse=level>=2&&rng.int(0,1),rms=peak/Math.sqrt(2);return make("sine_peak_rms",level,{body:inverse?"Vrms="+fmt(rms,3)+" V":"Vpeak="+peak+" V",fields:[inverse?nfield("peak","Vpeak",peak,"V",3):nfield("rms","Vrms",rms,"V",3)],topology:"sine-source",description:"Sinusoidal voltage source; peak and RMS references shown",labels:["sinusoid"],domain:"sinusoidal steady state",givens:{Vpeak:peak},steps:["Vrms=Vpeak/√2",inverse?"Vpeak=√2·Vrms":"Vrms="+fmt(rms,3)+" V"],signature:inverse?"rms-to-peak":"peak-to-rms"});};
