  G.meter_connection=function(level,rng){var voltage=rng.int(0,1);return make("meter_connection",level,{body:voltage?L("Measure voltage across R1.","Mät spänningen över R1."):L("Measure branch current through R1.","Mät grenströmmen genom R1."),fields:[choiceField("connection",L("Meter connection","Mätaranslutning"),voltage?"voltmeter in parallel":"ammeter in series",["voltmeter in parallel","voltmeter in series","ammeter in parallel","ammeter in series"])],topology:voltage?"meter-parallel":"meter-series",description:"Source and resistor R1 with an ideal "+(voltage?"voltmeter connected across both R1 nodes":"ammeter inserted in the R1 branch"),labels:["R1",voltage?"V":"A"],model:"ideal meter",steps:[voltage?"Voltage is a difference between two nodes → connect in parallel.":"Current flows through a branch → insert meter in series."],signature:voltage?"voltage":"current"});};
