    for(var i=0;i<1000;i++){var rng=new Rng(i),vs=V(5,rng),r1=R(5,rng),r2=R(5,rng),rl=R(5,rng),out=nodalDivider(vs,r1,r2,rl),lower=r2*rl/(r2+rl);assert("nodal agreement "+i,Math.abs(out-vs*lower/(r1+lower))<1e-12);var current=(vs-out)/r1;assert("KCL "+i,Math.abs(current-out/r2-out/rl)<1e-10);}
